"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[45338],{41572:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AccessPlayerClient","desc":"The client half of [AccessPlayerBase]. It reads what the server replicated onto the player instance\\nand feeds it into this realm\'s [AccessDataService], so a fact this realm can resolve and one only the\\nserver can are answered through the same path.\\n\\nBound to every player, so this realm can answer questions about anybody -- a party UI can show which\\nteammate is missing a chapter without asking them.","realm":["Client"],"source":{"line":13,"path":"src/access/src/Client/Binders/AccessPlayerClient.lua"}}')}}]);